Lemma fire_1RB1LC_0LC0RB_1LD0RD_1LA0RB : forall t, ~ In t pins_1RB1LC_0LC0RB_1LD0RD_1LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
