(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LC0RB_1LD1LA_1LA1LA : forall t, ~ In t pins_1RB1LC_0LC0RB_1LD1LA_1LA1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LC0RB_1LD1LA_1LA1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LC_0LC0RB_1LD1LA_1LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LC_0LC0RB_1LD1LA_1LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LC0RB_1LD1LA_1LA1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LC0RB_1LD1LA_1LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_0LC0RB_1LD1LA_1LA1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LC_0LC0RB_1LD1LA_1LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

